import{_ as t,o as n,c as r,O as l}from"./chunks/framework.2c2d5a61.js";const d=JSON.parse('{"title":"AI 与大模型","description":"","frontmatter":{},"headers":[],"relativePath":"interview/后端/Java/16-AI与大模型.md","filePath":"interview/后端/Java/16-AI与大模型.md","lastUpdated":1793001193000}'),s={name:"interview/后端/Java/16-AI与大模型.md"};function e(i,o,g,a,u,c){return n(),r("div",null,o[0]||(o[0]=[l('<h1 id="ai-与大模型" tabindex="-1">AI 与大模型 <a class="header-anchor" href="#ai-与大模型" aria-label="Permalink to &quot;AI 与大模型&quot;">​</a></h1><blockquote><p>配套知识点：<a href="./../../AI-Agent/">AI Agent 面试专题</a></p></blockquote><blockquote><p><strong>怎么用这份笔记</strong></p><ul><li>分级：<code>★★★ 必须吃透</code> / <code>★★☆ 了解即可（记结论就行）</code> / <code>★☆☆ 可以跳过（一句话看一眼）</code></li><li>每个考点按「定义 → 原理 → 要点 / 易错点」组织，只讲知识点</li></ul></blockquote><hr><h2 id="_1-大模型基础概念-llm、token、上下文窗口、temperature-★★★" tabindex="-1">1. 大模型基础概念：LLM、Token、上下文窗口、Temperature ★★★ <a class="header-anchor" href="#_1-大模型基础概念-llm、token、上下文窗口、temperature-★★★" aria-label="Permalink to &quot;1. 大模型基础概念：LLM、Token、上下文窗口、Temperature ★★★&quot;">​</a></h2><ul><li><strong>LLM（大语言模型）</strong>：基于 <strong>Transformer</strong>、在海量文本上<strong>预训练</strong>的模型。核心能力是<strong>自回归</strong>地「预测下一个 token」——每次生成一个 token 再接到后面继续预测，所以输出天然带<strong>概率性</strong>。</li><li><strong>Token</strong>：模型处理文本的<strong>最小单位</strong>。一个汉字大约 1–2 个 token，<strong>计费</strong>和上下文长度都按 token 计算。</li><li><strong>上下文窗口</strong>：单次「输入 + 输出」的 token 上限。<strong>输出也占额度</strong>，超出后必须截断、摘要或压缩。</li><li><strong>Temperature</strong>：控制输出随机性的参数。越低越稳定收敛（代码、事实问答用 0–0.3），越高越发散（写作、创意用 0.7–1）。</li></ul><p>两个工程含义：</p><ul><li>成本由 token 量决定，长上下文既贵、也容易让模型「注意力分散」，所以实践中只放最相关的片段，而不是把所有资料一股脑塞进去。</li><li>同一个模型在不同温度下表现差异很大，事实类任务不要用高温度。</li></ul><hr><h2 id="_2-大模型幻觉-hallucination-★★★" tabindex="-1">2. 大模型幻觉（Hallucination）★★★ <a class="header-anchor" href="#_2-大模型幻觉-hallucination-★★★" aria-label="Permalink to &quot;2. 大模型幻觉（Hallucination）★★★&quot;">​</a></h2><p><strong>幻觉</strong>指模型一本正经地编造事实：假数据、假引用、不存在的 API。</p><p>根因：</p><ul><li>模型的本质是「<strong>生成最像答案的内容</strong>」，而不是查库或校验事实；</li><li><strong>训练数据</strong>可能过时、有噪声、彼此冲突。</li></ul><p>缓解手段：</p><ul><li><strong>RAG</strong>：把真实资料检索出来放进上下文，让模型「照着答」；</li><li>限定知识范围，明确「资料中没有就回答没有」；</li><li><strong>Few-shot</strong> 给正确示例，约束输出风格；</li><li>降低 <strong>temperature</strong>，减少发散；</li><li>要求给出<strong>依据 / 出处</strong>，便于人工复核。</li></ul><p>结论：<strong>幻觉不能彻底消除，只能缓解</strong>。</p><hr><h2 id="_3-提示词工程-prompt-engineering-★★☆" tabindex="-1">3. 提示词工程（Prompt Engineering）★★☆ <a class="header-anchor" href="#_3-提示词工程-prompt-engineering-★★☆" aria-label="Permalink to &quot;3. 提示词工程（Prompt Engineering）★★☆&quot;">​</a></h2><p>用输入设计引导输出。常用手法：</p><ul><li><strong>角色设定</strong>：限定模型的身份与语体；</li><li><strong>Few-shot</strong>：给几个输入输出示例，示范期望行为；</li><li><strong>CoT 思维链</strong>：要求模型一步步推理再给结论；</li><li><strong>输出格式约束</strong>：JSON / Markdown / 固定字段，方便程序解析。</li></ul><p>组织套路：明确任务 → 给上下文 → 给示例 → 限定格式 → 要求依据。</p><p>CoT 之所以有效，是因为它让模型<strong>展开中间推理</strong>而不是一步跳到答案；代价是输出更长、延迟和成本更高。</p><hr><h2 id="_4-rag-检索增强生成-★★★-【重点-后端最该掌握】" tabindex="-1">4. RAG 检索增强生成 ★★★ 【重点，后端最该掌握】 <a class="header-anchor" href="#_4-rag-检索增强生成-★★★-【重点-后端最该掌握】" aria-label="Permalink to &quot;4. RAG 检索增强生成 ★★★ 【重点，后端最该掌握】&quot;">​</a></h2><p><strong>RAG = 检索（Retrieval）+ 增强（Augmented）+ 生成（Generation）</strong>。它解决三个问题：模型没见过<strong>私有文档</strong>、<strong>知识有截止时间</strong>、直接<strong>微调</strong>成本高。</p><p>流程五步：</p><ol><li><strong>切分</strong>：文档按语义或长度切成小片段（chunk）</li><li><strong>向量化</strong>：用 Embedding 模型把片段转成向量</li><li><strong>存储</strong>：写入向量库</li><li><strong>召回</strong>：问题同样向量化，按相似度（余弦）取 Top-K 片段</li><li><strong>拼接生成</strong>：把片段拼进 Prompt，交给 LLM 生成答案</li></ol><p>两个关键细节：</p><ul><li>切片要留有<strong>重叠（overlap）</strong>，避免语义在边界处被切断；</li><li>召回后可以加 <strong>Rerank 重排</strong>，提升最终送入模型的片段精度。</li></ul><hr><h2 id="_5-向量数据库-★★★" tabindex="-1">5. 向量数据库 ★★★ <a class="header-anchor" href="#_5-向量数据库-★★★" aria-label="Permalink to &quot;5. 向量数据库 ★★★&quot;">​</a></h2><p>传统数据库按「<strong>精确值</strong>」查，向量库按「<strong>语义相似</strong>」查，靠 <strong>ANN（近似最近邻）</strong> 索引加速，本质是用一点精度换查询速度。常见索引：</p><ul><li><strong>HNSW</strong>：图索引，查询快、内存占用高</li><li><strong>IVF</strong>：倒排聚类，先分桶再在桶内找</li><li><strong>PQ</strong>：量化压缩，大幅降低内存</li></ul><p>选型参考：</p><ul><li><strong>Milvus</strong>：专业向量库，适合大规模</li><li><strong>pgvector</strong>：PostgreSQL 插件，中小规模、运维省心</li><li><strong>Redis Vector</strong>：已有 Redis 栈可直接复用</li><li><strong>FAISS</strong>：偏底层库，不是独立服务</li></ul><hr><h2 id="_6-function-calling-tool-use-agent-★★★" tabindex="-1">6. Function Calling / Tool Use / Agent ★★★ <a class="header-anchor" href="#_6-function-calling-tool-use-agent-★★★" aria-label="Permalink to &quot;6. Function Calling / Tool Use / Agent ★★★&quot;">​</a></h2><ul><li><strong>Function Calling</strong>：模型不直接给答案，而是输出「调哪个函数 + 什么参数」，由<strong>应用真正执行</strong>，再把结果回填给模型继续生成。</li><li><strong>Agent</strong>：在工具调用之上让模型自己规划、多步执行，核心是「<strong>思考 → 行动 → 观察</strong>」循环（<strong>ReAct 模式</strong>）。</li><li><strong>职责分工</strong>：模型负责「决定调什么」，<strong>后端负责真正执行 + 参数校验</strong>。</li></ul><p>安全边界：模型输出<strong>不能</strong>直接拼进 SQL、Shell 命令或文件路径，必须在后端做白名单校验与参数转义，这是防注入的硬性要求。</p><hr><h2 id="_7-模型微调-fine-tuning-★★☆" tabindex="-1">7. 模型微调（Fine-tuning）★★☆ <a class="header-anchor" href="#_7-模型微调-fine-tuning-★★☆" aria-label="Permalink to &quot;7. 模型微调（Fine-tuning）★★☆&quot;">​</a></h2><ul><li><strong>预训练</strong>：在通用语料上训练底座模型。</li><li><strong>微调</strong>：在特定任务数据上继续训练，改变模型的风格、格式或领域能力。</li><li><strong>LoRA</strong>：只训练注入的<strong>低秩矩阵</strong>、冻结原权重，大幅降低显存和成本，是主流轻量方案。</li><li><strong>RLHF</strong>：用人类偏好数据对齐模型输出。</li></ul><p>选型原则：</p><ul><li>要引入<strong>私有知识</strong>、且要求能及时更新 → 用 <strong>RAG</strong></li><li>要稳定改变风格 / 输出格式 / 领域能力 → 才考虑<strong>微调</strong></li><li>多数业务优先 RAG，性价比更高</li></ul><hr><h2 id="_8-大模型应用工程-java-后端方向-★★★-【重点-最贴合我的栈】" tabindex="-1">8. 大模型应用工程（Java 后端方向）★★★ 【重点，最贴合我的栈】 <a class="header-anchor" href="#_8-大模型应用工程-java-后端方向-★★★-【重点-最贴合我的栈】" aria-label="Permalink to &quot;8. 大模型应用工程（Java 后端方向）★★★ 【重点，最贴合我的栈】&quot;">​</a></h2><ul><li><strong>Spring AI</strong>：Spring 官方 AI 框架，把各家模型（OpenAI、DeepSeek、通义、Ollama）<strong>统一成一套接口</strong>（ChatClient、EmbeddingModel），并封装 <strong>VectorStore</strong>、提示词模板、Function Calling、<strong>RAG 流程</strong>、<strong>流式输出</strong>；以 starter 形式与 Spring Boot 无缝集成。</li><li><strong>SSE 流式输出</strong>：模型生成慢，等整段返回体验太差，所以用 SSE 边生成边推（<strong>打字机效果</strong>）。 <ul><li>实现方式：Controller 返回 <code>SseEmitter</code>，分片 <code>send()</code>、最后 <code>complete()</code>；或返回 <code>Flux&lt;ServerSentEvent&gt;</code>（WebFlux）。</li></ul></li><li><strong>SSE 与 WebSocket 的区别</strong>：SSE 是<strong>单向</strong>（服务端 → 客户端）、基于 HTTP、自带重连、更轻、易穿网关；WebSocket 是<strong>双向全双工</strong>。大模型场景只需要服务端单向推送，所以 SSE 更合适。</li><li><strong>网关配置</strong>：Nginx 要<strong>关闭缓冲</strong>（<code>proxy_buffering off</code>）、设置长超时、加 <code>X-Accel-Buffering: no</code>，否则流式响应会被攒着一起发，打字机效果失效。</li><li>其他工程点：<strong>token 成本控制</strong>（限制 max_tokens、缓存 prompt）、<strong>多轮对话记忆</strong>（摘要压缩 / 滑动窗口）、<strong>超时重试降级</strong>（多模型冗余、限流）、<strong>内容安全</strong>（防 <strong>Prompt Injection</strong>）。</li></ul><hr><h2 id="附-一句话速记-可以跳过-★☆☆" tabindex="-1">附：一句话速记（可以跳过 ★☆☆） <a class="header-anchor" href="#附-一句话速记-可以跳过-★☆☆" aria-label="Permalink to &quot;附：一句话速记（可以跳过 ★☆☆）&quot;">​</a></h2><ul><li><strong>Transformer / 注意力机制</strong>：LLM 的底层架构，理解「<strong>自注意力</strong>让模型关注上下文相关部分」即可，面试问到不用展开公式。</li><li><strong>MoE（混合专家）</strong>：大模型省算力的架构思路，知道「<strong>按需激活部分专家</strong>」这个概念就行。</li><li><strong>多模态</strong>：模型能同时处理文本、图片、语音，了解<strong>概念</strong>即可。</li></ul>',50)]))}const h=t(s,[["render",e]]);export{d as __pageData,h as default};
